INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Kommunikations-Modelle > Vier-Seiten-Modell (Schulz von Thun)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Besteht jede Nachricht im Vier-Seiten-Modell aus vier Ebenen?', 2, '[{"text": "Ja", "correct": true, "because": "Sachinhalt, Beziehung, Selbstoffenbarung und Appell sind die vier Seiten"}, {"text": "Nein", "correct": false, "because": "Das Modell definiert vier Ebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Nachricht im Vier-Seiten-Modell unterschiedlich interpretiert werden, je nachdem welche Seite der Empfänger wahrnimmt?', 2, '[{"text": "Ja", "correct": true, "because": "Der Empfänger kann z. B. die Beziehungsebene stärker hören"}, {"text": "Nein", "correct": false, "because": "Interpretation variiert je nach Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Selbstoffenbarung im Vier-Seiten-Modell immer bewusst vom Sender gesteuert?', 2, '[{"text": "Nein", "correct": true, "because": "Selbstoffenbarung kann auch unbewusst erfolgen"}, {"text": "Ja", "correct": false, "because": "Unbewusste Signale sind Teil dieser Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Missverständnisse im Vier-Seiten-Modell entstehen, wenn Sender und Empfänger auf unterschiedlichen Ebenen kommunizieren?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Sender meint Sachinhalt, Empfänger hört Appell"}, {"text": "Nein", "correct": false, "because": "Unterschiedliche Ebenen führen oft zu Konflikten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Appell im Vier-Seiten-Modell immer explizit formuliert?', 2, '[{"text": "Nein", "correct": true, "because": "Appelle können implizit in der Nachricht enthalten sein"}, {"text": "Ja", "correct": false, "because": "Appelle sind oft unterschwellig"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Ebene des Vier-Seiten-Modells beschreibt die Fakten einer Nachricht?', 3, '[{"text": "Sachinhalt", "correct": true, "because": "Bezieht sich auf die reine Information"}, {"text": "Beziehung", "correct": false, "because": "Zeigt die Beziehungsebene"}, {"text": "Appell", "correct": false, "because": "Fordert eine Handlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Seite des Vier-Seiten-Modells gibt Aufschluss über die Beziehung zwischen Sender und Empfänger?', 2, '[{"text": "Beziehungsebene", "correct": true, "because": "Zeigt die emotionale Verbindung"}, {"text": "Selbstoffenbarung", "correct": false, "because": "Bezieht sich auf den Sender"}, {"text": "Sachinhalt", "correct": false, "because": "Nur Fakten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Vier-Seiten-Modells?', 2, '[{"text": "Verständnis von Kommunikationskomplexität", "correct": true, "because": "Zeigt Mehrdimensionalität"}, {"text": "Vermeidung jeglicher Kommunikation", "correct": false, "because": "Gegenteil ist Ziel"}, {"text": "Reduktion auf eine Ebene", "correct": false, "because": "Modell betont vier Ebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann laut Vier-Seiten-Modell entstehen, wenn der Empfänger die Beziehungsebene überinterpretiert?', 3, '[{"text": "Missverständnis der Absicht", "correct": true, "because": "Fokus auf Beziehung statt Sachinhalt"}, {"text": "Schnellere Verständigung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Klärung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebene des Vier-Seiten-Modells zeigt, was der Sender über sich selbst preisgibt?', 2, '[{"text": "Selbstoffenbarung", "correct": true, "because": "Offenbart Persönliches"}, {"text": "Appell", "correct": false, "because": "Fordert etwas vom Empfänger"}, {"text": "Sachinhalt", "correct": false, "because": "Nur Fakten"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Ebenen gehören zum Vier-Seiten-Modell?', 4, '[{"text": "Sachinhalt", "correct": true, "because": "Fakten der Nachricht"}, {"text": "Beziehung", "correct": true, "because": "Emotionale Verbindung"}, {"text": "Selbstoffenbarung", "correct": true, "because": "Sender-Information"}, {"text": "Technische Details", "correct": false, "because": "Nicht Teil des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können im Vier-Seiten-Modell zu Missverständnissen führen?', 3, '[{"text": "Unterschiedliche Wahrnehmung der Ebenen", "correct": true, "because": "Sender und Empfänger hören verschieden"}, {"text": "Unbewusste Selbstoffenbarung", "correct": true, "because": "Kann falsch interpretiert werden"}, {"text": "Verdeckter Appell", "correct": true, "because": "Nicht klar ausgesprochen"}, {"text": "Schnelle Kommunikation", "correct": false, "because": "Kein direkter Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf das Vier-Seiten-Modell zu?', 4, '[{"text": "Jede Nachricht hat vier Seiten", "correct": true, "because": "Grundprinzip des Modells"}, {"text": "Der Empfänger kann Ebenen unterschiedlich gewichten", "correct": true, "because": "Interpretation variiert"}, {"text": "Es erklärt Kommunikationskonflikte", "correct": true, "because": "Zeigt Mehrdimensionalität"}, {"text": "Es gilt nur für schriftliche Kommunikation", "correct": false, "because": "Umfasst alle Formen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele zeigen die Beziehungsebene im Vier-Seiten-Modell?', 3, '[{"text": "Tonfall der Stimme", "correct": true, "because": "Vermittelt Beziehung"}, {"text": "Wortwahl", "correct": true, "because": "Zeigt Haltung zum Empfänger"}, {"text": "Körpersprache", "correct": true, "because": "Nonverbaler Ausdruck"}, {"text": "Technische Daten", "correct": false, "because": "Sachinhalt, nicht Beziehung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Vier-Seiten-Modell?', 3, '[{"text": "Klarheit über Kommunikationsprozesse", "correct": true, "because": "Zeigt Ebenen auf"}, {"text": "Verständnis für Missverständnisse", "correct": true, "because": "Erklärt Konflikte"}, {"text": "Verbesserung der Kommunikation", "correct": true, "because": "Sensibilisiert für Ebenen"}, {"text": "Reduktion auf technische Fakten", "correct": false, "because": "Gegenteil ist Ziel"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Vier-Seiten-Modell zeigt, dass jede Nachricht mehrere Ebenen hat. b) Der Empfänger nimmt immer alle Ebenen gleich wahr.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Ebenen ja, Wahrnehmung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Selbstoffenbarung kann unbewusst erfolgen. b) Der Sachinhalt ist immer das Wichtigste im Modell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unbewusst ja, Gewichtung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Appell kann im Vier-Seiten-Modell unterschwellig sein. b) Das Modell gilt nur für technische Kommunikation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterschwellig ja, allgemein anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Beziehungsebene beeinflusst die Interpretation einer Nachricht. b) Im Vier-Seiten-Modell gibt es nur zwei Ebenen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beziehung ja, vier Ebenen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Vier-Seiten-Modell hilft, Kommunikationskonflikte zu verstehen. b) Der Sender kontrolliert immer alle vier Ebenen vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konflikte ja, Kontrolle begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

